    public static bool TryGetReleaseTag(string fileName, out string releaseTag)
    {
        if (Assets.TryGetValue(fileName, out string? value))
        {
            releaseTag = value;
            return true;
        }
        releaseTag = string.Empty;
        return false;
    }
